            Tags = """["sales-channels","quick-reference"]""",
            ContentJson = """{"title":"Sales Channels Field Reference","groups":[{"heading":"Channel form","items":[{"label":"Name (required)","value":"How the channel appears on cards, in order pickers and on filters."},{"label":"Code (required)","value":"Short identifier, up to 40 characters. Cannot change after saving because order numbers and integrations key on it."},{"label":"Channel type (required)","value":"Account business, Direct retail, or Marketplace. Cannot change after saving. Retail and Marketplace unlock the house account and store connection fields."},{"label":"Bills to (house account)","value":"Required on retail and marketplace channels. The one customer record that owes you for every order on the channel. Buyers never bill directly."},{"label":"Store connection","value":"Optional. Attach a storefront or marketplace connection to pull orders and listings from it. Leave empty for a manual channel."},{"label":"Sales tax collected by","value":"Use the type's default, We collect and remit, or the marketplace collects. Marketplace-collected tax shows on orders but is never your liability."},{"label":"Order number prefix","value":"Optional, up to 10 characters. Starts a separate numbering series for this channel."},{"label":"Description","value":"Free text shown on the card."}]},{"heading":"Card chips and actions","items":[{"label":"Default","value":"Orders created without a channel belong to this one. Never a retail channel. Cannot be deleted."},{"label":"Retired","value":"Inactive. Hidden until Show retired is on. Retire instead of deleting a channel that has orders or buyers."},{"label":"Marketplace collects tax","value":"The platform collects and remits sales tax on this channel's orders."},{"label":"Import orders","value":"Shown on channels with a store connection. Pulls new orders in now; orders already seen are skipped."},{"label":"Make default","value":"Moves the default to this channel."}]},{"heading":"Store connection form","items":[{"label":"Name (required)","value":"Your label for the storefront account."},{"label":"Platform (required)","value":"Shopify or WooCommerce today. Cannot change after saving; create a new connection instead."},{"label":"Store URL","value":"Shopify: your myshopify host, e.g. my-store.myshopify.com. WooCommerce: the store's base URL."},{"label":"Credentials (required on create)","value":"Shopify: the Admin API access token (starts with shpat_). WooCommerce: consumer_key:consumer_secret. On edit, blank keeps what is stored."},{"label":"Import orders automatically","value":"Poll the store for new orders on a schedule."},{"label":"Push inventory levels back","value":"Send Forge stock counts to the store for mapped listings."},{"label":"Enabled","value":"Edit only. Turn a connection off without deleting it."},{"label":"Test connection","value":"Checks the stored credentials against the platform."}]},{"heading":"Retail order form","items":[{"label":"Channel (required)","value":"Which retail channel the order belongs to. Decides the house account and tax treatment."},{"label":"Buyer name / Email / Phone","value":"The consumer. Name is required. Recorded as a retail buyer, not a customer."},{"label":"Agreed to marketing contact","value":"Tick only if the buyer actually said yes. A sale is not consent."},{"label":"Ship to","value":"Recipient, address, city, state, postal code, country. Frozen on the order; not added to any address book."},{"label":"Items","value":"Description, optional SKU, quantity and the unit price actually charged. Retail prices are not resolved from a price list."},{"label":"Shipping charged / Tax rate","value":"Added to the order total shown at the bottom."}]},{"heading":"Listing statuses","items":[{"label":"Unmapped","value":"No Forge part behind this SKU. Orders still import; their lines arrive without a part until you map it."},{"label":"Never pushed","value":"No inventory level has been sent to the store for this listing yet."},{"label":"Sync from channel","value":"Pulls the store's catalog. Needs a channel picked in the filter first."}]},{"heading":"Settlement statuses","items":[{"label":"Imported","value":"Batch is in but not yet checked."},{"label":"Ties out","value":"Line detail adds up to the amount the marketplace reported paying."},{"label":"Needs review","value":"Line detail does not add up. Open the batch to see the variance and any unmatched lines."},{"label":"Accepted","value":"Someone recorded a reason for the variance. No longer shown as an exception."},{"label":"Unmatched line","value":"Names an order Forge never imported, so its amount cannot be attributed."}]},{"heading":"Retail buyers","items":[{"label":"Lifetime value","value":"Total of the buyer's orders on that channel."},{"label":"Scrub personal details","value":"Removes name, email, phone and shipping addresses permanently. Orders, counts and totals are kept. Row shows Scrubbed afterward."}]}]}"""
        });

